import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Grok Learning Map","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/index.md","filePath":"products/ai-coding/grok/index.md","lastUpdated":1787107158000}'),s={name:"products/ai-coding/grok/index.md"};function n(i,e,d,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="grok-learning-map" tabindex="-1">Grok Learning Map <a class="header-anchor" href="#grok-learning-map" aria-label="Permalink to &quot;Grok Learning Map&quot;">​</a></h1><blockquote><p><strong>Grok Build</strong> is xAI&#39;s first-party terminal coding agent. The executable is named <code>grok</code>, and the source is open at <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">xai-org/grok-build</a>.</p><p>Official definition (<a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">docs.x.ai/build/overview</a>): &quot;<strong>Grok Build</strong> is a powerful and extensible coding agent. Use it via an interactive TUI, headlessly in scripts or bots, or through the Agent Client Protocol (ACP) in other apps.&quot;</p></blockquote><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>Several xAI products share the word &quot;Grok&quot; or &quot;Build&quot;. They are <strong>not</strong> one product with four skins. The <strong>core learning path</strong> in this directory is <strong>Grok Build</strong> (the terminal coding agent). The other official surfaces now have their own pages so you do not pick the wrong door.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xAI / Grok family</span></span>
<span class="line"><span>├── Grok (chat) — grok.com, iOS, Android, and X</span></span>
<span class="line"><span>│   ├── Chat / search / voice / file upload</span></span>
<span class="line"><span>│   ├── Imagine — images and video (also grok.com/imagine)</span></span>
<span class="line"><span>│   └── Build Mode — chat-native sites / apps / games, publish to grok.me</span></span>
<span class="line"><span>├── Grok Build — terminal coding agent (the \`grok\` command)</span></span>
<span class="line"><span>│   ├── Interactive TUI</span></span>
<span class="line"><span>│   ├── Headless (\`grok -p\`)</span></span>
<span class="line"><span>│   └── ACP (\`grok agent stdio\`)</span></span>
<span class="line"><span>├── Grok Bot — named teammates on a persistent cloud computer</span></span>
<span class="line"><span>└── xAI API — model HTTP API, including the Imagine API</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Product</th><th>What it is</th><th>Entry point</th><th>Analog in the Claude family</th></tr></thead><tbody><tr><td><strong>Grok Build</strong></td><td>Terminal coding agent for a real repo</td><td>the <code>grok</code> command</td><td>Claude Code CLI</td></tr><tr><td><a href="./grok-chat.html">Grok (chat)</a></td><td>General-purpose assistant</td><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a>, Grok apps, X</td><td>Claude.ai</td></tr><tr><td><a href="./grok-imagine.html">Imagine</a></td><td>Image and video generation / editing</td><td><a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a>, or the <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">Imagine API</a></td><td>Claude Design (creative surface, not a coding agent)</td></tr><tr><td><a href="./grok-voice.html">Voice</a></td><td>Hands-free talk in the app + Voice API</td><td>grok.com / apps; <a href="https://docs.x.ai/developers/model-capabilities/audio/voice" target="_blank" rel="noreferrer">Voice API</a></td><td>Claude voice / realtime API</td></tr><tr><td><a href="./grok-connectors.html">Connectors</a></td><td>Email / files / calendar / custom MCP inside chat</td><td><a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a></td><td>Claude Connectors</td></tr><tr><td>Build Mode</td><td>Chat-native builder; publish a live link</td><td>Mode switcher <strong>Build</strong> on grok.com / Grok apps</td><td>Claude.ai Artifacts-style creation, <strong>not</strong> Claude Code</td></tr><tr><td><a href="./grok-bot.html">Grok Bot</a></td><td>Always-on teammates on a shared cloud VM</td><td><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a> desktop + iOS apps</td><td>Cowork (task agent, not a repo CLI)</td></tr><tr><td><a href="./grok-business.html">Grok Business</a></td><td>Team workspaces, licenses, org controls</td><td><a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>Claude Team / Enterprise</td></tr><tr><td>xAI API</td><td>Model / Imagine / Voice HTTP API</td><td><a href="https://docs.x.ai/developers/quickstart" target="_blank" rel="noreferrer">docs.x.ai/developers/quickstart</a></td><td>Anthropic API</td></tr></tbody></table><p><strong>Names that collide:</strong></p><ul><li><strong>Grok Build</strong> ≠ <strong>Build Mode</strong>. Grok Build is the terminal agent (<code>docs.x.ai/build/*</code>). Build Mode is a grok.com chat mode: &quot;Tell Grok an idea, and it builds a working version live in your chat&quot; and you &quot;Publish to a grok.me link or a custom domain you own&quot; (<a href="https://x.ai/news/grok-build-mode" target="_blank" rel="noreferrer">x.ai/news/grok-build-mode</a>, <a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>). Early Beta for <strong>SuperGrok Heavy</strong> on web, iOS, and Android. Official density is still a marketing page + one news post, so it stays on this map instead of a standalone tutorial.</li><li><strong>grok.me</strong> is the <strong>publish host</strong> for Build Mode. It is not a separate product and not the Grok Build CLI.</li><li><strong>Grok Bot</strong> ≠ Grok Build headless &quot;bots&quot;. Grok Bot is a desktop / iOS product with its own docs tree at <a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot</a>.</li><li>There is <strong>no official IDE plugin</strong>. Editor use of Grok Build is ACP (<code>grok agent stdio</code>). <a href="https://docs.x.ai/build/cli/terminal-support" target="_blank" rel="noreferrer">terminal-support</a> only documents key-binding differences inside VS Code / Cursor / Windsurf / Zed terminals.</li></ul><p>Accounts are <strong>not</strong> one pool. Grok Build accepts a SuperGrok / X Premium Plus login or <code>XAI_API_KEY</code>. Grok Bot authenticates with a <strong>Cursor</strong> account and is gated to SuperGrok Heavy, Cursor Ultra, and Cursor Teams Premium (<a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a>). Build Mode&#39;s Early Beta is SuperGrok Heavy only.</p><h3 id="quick-decision-which-surface" tabindex="-1">Quick decision: which surface? <a class="header-anchor" href="#quick-decision-which-surface" aria-label="Permalink to &quot;Quick decision: which surface?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do I want to do?</span></span>
<span class="line"><span>├── Write / debug / refactor / open a PR in a real repository</span></span>
<span class="line"><span>│   └── → Grok Build (\`grok\`)</span></span>
<span class="line"><span>│       ├── In the terminal? → TUI (\`grok\`)</span></span>
<span class="line"><span>│       ├── In CI / scripts? → headless (\`grok -p\`)</span></span>
<span class="line"><span>│       └── Inside an editor? → ACP (\`grok agent stdio\`) — no official VS Code plugin</span></span>
<span class="line"><span>├── Chat / write / research / voice / upload files</span></span>
<span class="line"><span>│   └── → [Grok Chat](./grok-chat.md) on grok.com or the Grok iOS / Android apps</span></span>
<span class="line"><span>│       ├── Hands-free talk → [Voice](./grok-voice.md) (product; Voice API is separate)</span></span>
<span class="line"><span>│       └── Email / Drive / calendar in-thread → [Connectors](./grok-connectors.md)</span></span>
<span class="line"><span>├── Generate or edit images / video</span></span>
<span class="line"><span>│   └── → [Imagine](./grok-imagine.md)</span></span>
<span class="line"><span>│       ├── In the product? → grok.com/imagine (also inside grok.com chat)</span></span>
<span class="line"><span>│       └── From my own app? → Imagine API</span></span>
<span class="line"><span>├── Build a website / app / game in chat and share a link</span></span>
<span class="line"><span>│   └── → Build Mode (grok.com mode switcher → Build)</span></span>
<span class="line"><span>│       └── SuperGrok Heavy Early Beta; publish to grok.me or a custom domain</span></span>
<span class="line"><span>├── Hand real work to a teammate that keeps going when the laptop is closed</span></span>
<span class="line"><span>│   └── → [Grok Bot](./grok-bot.md) (desktop + iOS)</span></span>
<span class="line"><span>│       └── SuperGrok Heavy / Cursor Ultra / Cursor Teams Premium</span></span>
<span class="line"><span>├── Team workspaces / licenses / org sharing</span></span>
<span class="line"><span>│   └── → [Grok Business](./grok-business.md)</span></span>
<span class="line"><span>└── Call models from my own software</span></span>
<span class="line"><span>    └── → xAI API</span></span></code></pre></div><p>Sources: <a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a>, <a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">docs.x.ai/build/overview</a>, <a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a>, <a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a>, <a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>, <a href="https://x.ai/news/grok-build-mode" target="_blank" rel="noreferrer">x.ai/news/grok-build-mode</a>, <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">docs.x.ai/developers/model-capabilities/imagine</a>, <a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a>.</p><h2 id="three-grok-build-surfaces" tabindex="-1">Three Grok Build surfaces <a class="header-anchor" href="#three-grok-build-surfaces" aria-label="Permalink to &quot;Three Grok Build surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Entry point</th><th>Where it fits</th></tr></thead><tbody><tr><td>Interactive TUI</td><td><code>grok</code></td><td>Day-to-day development, full-screen terminal UI</td></tr><tr><td>Headless</td><td><code>grok -p &quot;&lt;prompt&gt;&quot;</code></td><td>Scripts, CI, batch jobs</td></tr><tr><td>ACP</td><td><code>grok agent stdio</code></td><td>Embedded by editors or your own orchestrator (JSON-RPC over stdin/stdout)</td></tr></tbody></table><p>Sources: <a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">docs.x.ai/build/overview</a>, <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">docs.x.ai/build/cli/reference</a></p><h2 id="when-grok-build-is-worth-trying" tabindex="-1">When Grok Build is worth trying <a class="header-anchor" href="#when-grok-build-is-worth-trying" aria-label="Permalink to &quot;When Grok Build is worth trying&quot;">​</a></h2><p><strong>Try it when</strong></p><ul><li>You already use Claude Code and want a cheap side-by-side comparison. xAI explicitly claims zero-configuration compatibility (it reads <code>CLAUDE.md</code> and <code>.claude/settings.json</code>, accepts Claude Code flag aliases, and <code>grok import</code> pulls in Claude Code sessions), so migration cost is close to zero.</li><li>You need long-running orchestration in the terminal: background tasks, scheduled loops, parallel subagents, and worktree isolation are all built in.</li><li>You already subscribe to SuperGrok or X Premium Plus (the <a href="https://x.ai/news/grok-build-cli" target="_blank" rel="noreferrer">launch announcement</a> says: Available now to all SuperGrok and X Premium Plus subscribers), or you have an <code>XAI_API_KEY</code>.</li></ul><p><strong>Hold off when</strong></p><ul><li>You want inline IDE completion — Grok Build is a terminal agent with no completion feature and no official IDE plugin.</li><li>You need a teammate that keeps working after you close the laptop — that is <a href="./grok-bot.html">Grok Bot</a>, not Grok Build.</li><li>You want a no-install chat builder that publishes a <code>*.grok.me</code> link — that is Build Mode on grok.com, SuperGrok Heavy Early Beta.</li><li>You need a stable long-term surface — Grok Build is still beta. npm <code>@xai-official/grok</code> moved <code>latest</code> from 1.0.3 (2026-08-12) to 1.0.5 (2026-08-16); commands and config keys are still moving. Check <code>grok version</code> and the <a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">changelog</a> before pinning anything.</li></ul><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Get it running</td><td>Install and auth in the <a href="./grok-cli.html">Grok Build tutorial</a></td><td>First conversation within 15 minutes</td></tr><tr><td>2. Learn the core</td><td>TUI / plan mode / permissions in the <a href="./grok-cli.html">tutorial</a></td><td>Confident enough to let it edit code</td></tr><tr><td>3. Wire it into your workflow</td><td><a href="./grok-cookbook.html">Cookbook</a></td><td>headless, CI, hooks, MCP, subagents</td></tr><tr><td>4. Look up parameters</td><td><a href="./grok-cheatsheet.html">Cheatsheet</a></td><td>Commands, flags, config keys, env vars, pricing</td></tr><tr><td>5. Understand the concepts</td><td><a href="./grok-glossary.html">Glossary</a></td><td>Permission mode vs. sandbox, skill vs. plugin, memory vs. session</td></tr></tbody></table><h2 id="feature-index" tabindex="-1">Feature index <a class="header-anchor" href="#feature-index" aria-label="Permalink to &quot;Feature index&quot;">​</a></h2><p>Only capabilities that have an official documentation page are listed. Each row links to the primary source.</p><table tabindex="0"><thead><tr><th>Capability</th><th>In one line</th><th>Official docs</th></tr></thead><tbody><tr><td>Plan mode</td><td>Draft a plan, get approval, then act</td><td><a href="https://docs.x.ai/build/features/plan-mode" target="_blank" rel="noreferrer">plan-mode</a></td></tr><tr><td>Permission rules</td><td><code>allow</code> / <code>ask</code> / <code>deny</code> rules matched against tool calls</td><td><a href="https://docs.x.ai/build/features/permissions" target="_blank" rel="noreferrer">permissions</a></td></tr><tr><td>Sandbox</td><td>OS-level isolation via Landlock / Seatbelt, five profiles</td><td><a href="https://docs.x.ai/build/features/sandbox" target="_blank" rel="noreferrer">sandbox</a></td></tr><tr><td>Project rules</td><td>Reads <code>AGENTS.md</code>, and also <code>CLAUDE.md</code> / <code>.cursor/rules</code></td><td><a href="https://docs.x.ai/build/features/project-rules" target="_blank" rel="noreferrer">project-rules</a></td></tr><tr><td>Skills</td><td><code>SKILL.md</code> defines reusable capability, callable as <code>/&lt;name&gt;</code></td><td><a href="https://docs.x.ai/build/features/skills-plugins-marketplaces" target="_blank" rel="noreferrer">skills-plugins-marketplaces</a></td></tr><tr><td>Plugins / Marketplace</td><td>Package skills + commands + agents + hooks + MCP for distribution</td><td><a href="https://docs.x.ai/build/features/skills-plugins-marketplaces" target="_blank" rel="noreferrer">skills-plugins-marketplaces</a></td></tr><tr><td>Hooks</td><td>Lifecycle events trigger external commands; can block tool calls</td><td><a href="https://docs.x.ai/build/features/hooks" target="_blank" rel="noreferrer">hooks</a></td></tr><tr><td>MCP</td><td><code>grok mcp add</code>; tools are namespaced as <code>&lt;server&gt;__&lt;tool&gt;</code></td><td><a href="https://docs.x.ai/build/features/mcp-servers" target="_blank" rel="noreferrer">mcp-servers</a></td></tr><tr><td>Subagents / Personas</td><td>Built-in <code>general-purpose</code> / <code>explore</code> / <code>plan</code>, plus custom types</td><td><a href="https://docs.x.ai/build/features/subagents" target="_blank" rel="noreferrer">subagents</a></td></tr><tr><td>Sessions</td><td>Indexed by working directory; resume / fork / rewind / compact</td><td><a href="https://docs.x.ai/build/features/sessions" target="_blank" rel="noreferrer">sessions</a></td></tr><tr><td>Worktrees</td><td>Work in an isolated checkout under <code>~/.grok/worktrees/</code></td><td><a href="https://docs.x.ai/build/features/worktrees" target="_blank" rel="noreferrer">worktrees</a></td></tr><tr><td>Background tasks</td><td>Task panel plus <code>/loop</code> scheduled repeats</td><td><a href="https://docs.x.ai/build/features/background-tasks" target="_blank" rel="noreferrer">background-tasks</a></td></tr><tr><td>Dashboard</td><td>Multi-session status overview</td><td><a href="https://docs.x.ai/build/features/dashboard" target="_blank" rel="noreferrer">dashboard</a></td></tr><tr><td>Headless</td><td><code>-p</code> for one-shot prompts, <code>--output-format</code> for JSON</td><td><a href="https://docs.x.ai/build/cli/headless-scripting" target="_blank" rel="noreferrer">headless-scripting</a></td></tr><tr><td>ACP</td><td><code>grok agent stdio</code> runs as an ACP agent for a host app</td><td><a href="https://docs.x.ai/build/cli/headless-scripting" target="_blank" rel="noreferrer">headless-scripting</a></td></tr><tr><td>Enterprise policy</td><td>Five config layers, OIDC, MDM-managed policy</td><td><a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">enterprise</a></td></tr><tr><td>Theming</td><td>Built-in GrokNight / GrokDay and others, can follow the system</td><td><a href="https://docs.x.ai/build/features/theming" target="_blank" rel="noreferrer">theming</a></td></tr></tbody></table><h2 id="model-reference" tabindex="-1">Model reference <a class="header-anchor" href="#model-reference" aria-label="Permalink to &quot;Model reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model slug</th><th>Positioning (official wording)</th><th>Context</th></tr></thead><tbody><tr><td><code>grok-4.6</code></td><td>&quot;For everything else, including code, use Grok 4.6. It is the most intelligent and fastest model we&#39;ve built.&quot;</td><td>500k</td></tr><tr><td><code>grok-build-0.1</code></td><td>&quot;xAI&#39;s coding model, trained specifically for agentic coding workflows.&quot;</td><td>256k</td></tr></tbody></table><p>The current banner on <a href="https://x.ai/build" target="_blank" rel="noreferrer">x.ai/build</a> reads &quot;Meet Grok 4.6 • Now powering Grok Build&quot;, so the default driving model is <code>grok-4.6</code>. Pricing and limits are in the <a href="./grok-cheatsheet.html#models-and-pricing">cheatsheet</a>.</p><p>Sources: <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a>, <a href="https://docs.x.ai/developers/release-notes" target="_blank" rel="noreferrer">developers/release-notes</a></p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li>Official CLI docs: <a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">https://docs.x.ai/build/overview</a></li><li>Official API docs: <a href="https://docs.x.ai/developers/quickstart" target="_blank" rel="noreferrer">https://docs.x.ai/developers/quickstart</a></li><li>CLI changelog: <a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">https://x.ai/build/changelog</a></li><li>Source repository: <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">https://github.com/xai-org/grok-build</a></li><li>Official plugin marketplace: <a href="https://github.com/xai-org/plugin-marketplace" target="_blank" rel="noreferrer">https://github.com/xai-org/plugin-marketplace</a></li><li>A fuller source list (with access notes) lives in the <a href="./grok-cheatsheet.html#high-quality-sources">cheatsheet&#39;s &quot;High-quality sources&quot; section</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./grok-cli.html">Grok Build tutorial</a> — install, auth, TUI, headless, ACP</li><li><a href="./grok-cookbook.html">Cookbook</a> — task-oriented recipes</li><li><a href="./grok-cheatsheet.html">Cheatsheet</a> — commands / config / env vars / pricing / sources</li><li><a href="./grok-glossary.html">Glossary</a> — what the concepts are and why</li><li><a href="./grok-chat.html">Grok Chat</a> — grok.com / iOS / Android</li><li><a href="./grok-imagine.html">Imagine</a> — images and video</li><li><a href="./grok-voice.html">Voice</a> — product Voice + Voice API</li><li><a href="./grok-connectors.html">Connectors</a> — email / files / calendar in chat</li><li><a href="./grok-bot.html">Grok Bot</a> — cloud-computer teammates (not the CLI)</li><li><a href="./grok-business.html">Grok Business</a> — team workspaces</li><li><a href="./../">AI coding tools overview</a></li></ul>`,33)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
